export function invariant(value, message) {
  if (value == null) {
    throw new Error(message);
  }
  return value;
}

// The router's own open write (`Object.assign(obj, written)` in its static
// integration): under ADR 0284 it vetoes every member of the objects this
// package creates.
export function assignAll(target, source) {
  return Object.assign(target, source);
}
